--DS d_script_carrier_info
SELECT 'CARRIERDET' carrierdet, invoice_hdr.invoice_no,oe_pick_ticket.pick_ticket_no, COALESCE(clippership_return_10004.carrier_name, invoice_hdr.carrier_name, carrier.name) c_carrier,COALESCE(ups_packages.tracking_number, oe_hdr_fedex_info_detail.fedex_tracking_number, clippership_return_10004.tracking_no, oe_pick_ticket.tracking_no) c_tracking_noFROM invoice_hdrINNER JOIN oe_pick_ticket ON ( invoice_hdr.invoice_no = oe_pick_ticket.invoice_id_when_shipped )LEFT JOIN clippership_return_10004 ON ( clippership_return_10004.pick_ticket_no = oe_pick_ticket.pick_ticket_no )AND ( clippership_return_10004.delete_flag = 'N')LEFT JOIN shipment ON ( shipment.transaction_type_cd = 1000 )AND ( shipment.transaction_no = oe_pick_ticket.pick_ticket_no )AND ( shipment.row_status_flag = 2175 )LEFT JOIN address AS carrier ON ( carrier.id = oe_pick_ticket.carrier_id )LEFT JOIN p21_view_shipped_ups_package_details AS ups_packages ON ( ups_packages.shipment_uid = shipment.shipment_uid )LEFT JOIN oe_hdr_fedex_info_detail ON oe_hdr_fedex_info_detail.pick_ticket_no = oe_pick_ticket.pick_ticket_noWHERE ( ISNUMERIC( invoice_hdr.invoice_no ) = 1 )AND invoice_hdr.invoice_no IN ( '3069750' )UNION ALLSELECT 'CARRIERDET' carrierdet, invoice_hdr.invoice_no,oe_pick_ticket.pick_ticket_no, COALESCE(clippership_return_10004.carrier_name, invoice_hdr.carrier_name, carrier.name) c_carrier,COALESCE(ups_packages.tracking_number, oe_hdr_fedex_info_detail.fedex_tracking_number, clippership_return_10004.tracking_no, oe_pick_ticket.tracking_no) c_tracking_noFROM invoice_hdrINNER JOIN oe_pick_ticket ON (invoice_hdr.record_type_cd = 2594 AND invoice_hdr.record_type_reference_no = oe_pick_ticket.invoice_id_when_shipped)LEFT JOIN clippership_return_10004 ON ( clippership_return_10004.pick_ticket_no = oe_pick_ticket.pick_ticket_no )AND ( clippership_return_10004.delete_flag = 'N')LEFT JOIN shipment ON ( shipment.transaction_type_cd = 1000 )AND ( shipment.transaction_no = oe_pick_ticket.pick_ticket_no )AND ( shipment.row_status_flag = 2175 )LEFT JOIN address AS carrier ON ( carrier.id = oe_pick_ticket.carrier_id )LEFT JOIN p21_view_shipped_ups_package_details AS ups_packages ON ( ups_packages.shipment_uid = shipment.shipment_uid )LEFT JOIN oe_hdr_fedex_info_detail ON oe_hdr_fedex_info_detail.pick_ticket_no = oe_pick_ticket.pick_ticket_noWHERE ( ISNUMERIC( invoice_hdr.invoice_no ) = 1 )AND invoice_hdr.invoice_no IN ( '3069750' )